INSERT INTO public.products (category_id, name, description, image_url, is_available)
VALUES
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Caléndula', 'Bálsamo calmante y regenerador elaborado con flores de caléndula y cera pura de abejas. Alivia paspaduras, dermatitis, eczemas y pieles sensibles o irritadas.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Rosa Mosqueta', 'Nutrición facial intensiva y regenerador celular natural. Rica en ácidos grasos esenciales y antioxidantes. Atenúa cicatrices, manchas y líneas de expresión.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Ortiga', 'Fórmula descongestiva y activadora de la circulación periférica. Alivia dolores reumáticos, pesadez en piernas cansadas y molestias por várices.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Diente de León', 'Depurativa cutánea y revitalizante celular. Ayuda a atenuar manchas dérmicas, estimula la eliminación de toxinas en la piel y aporta luminosidad.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Consuelda', 'Poderoso regenerador celular con alantoína natural. Indicada para fisuras, regeneración de tejidos, contusiones óseas, ligamentos y articulaciones.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Cannabis', 'Alivio profundo para dolores articulares y musculares crónicos. Potente acción antiinflamatoria y calmante local para contracturas y rigidez.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Hipérico', 'Pomada bermellón a base de flor de San Juan. Regeneradora de terminaciones nerviosas, alivia dolores neurálgicos, quemaduras leves y golpes.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Pañil', 'Arbusto medicinal patagónico con alta capacidad cicatrizante. Recomendada para úlceras dérmicas, grietas, heridas de difícil curación y afecciones cutáneas.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Enebro', 'Pomada calorífica y descontracturante. Con bayas de enebro andino, ideal para masajes previos a la actividad física o para disipar rigidez tensional.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Cúrcuma', 'Potente antioxidante y antiinflamatorio natural. Alivia inflamaciones articulares localizadas y protege la piel contra el envejecimiento prematuro.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Orégano', 'Antifúngica y antibacteriana natural. Indicada para combatir micosis dérmicas, pie de atleta, sarpullidos y pruritos con acción descongestiva.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Alcanfor', 'Refrescante y estimulante. Alivia la sensación de fatiga muscular extrema, reactiva el flujo sanguíneo y despeja zonas de sobrecarga tensional.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema Bálsamo Pectoral', 'Ungüento balsámico con esencias pectorales cordilleranas. Alivia resfríos, tos y congestión nasal mediante masajes suaves en pecho, cuello y espalda.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema MIX 31', 'Sinergia maestra de 31 hierbas botánicas puras. Proporciona bienestar integral, relaja tensiones musculares acumuladas y refresca los sentidos.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema Articulaciones', 'Fórmula combinada de hierbas andinas para artrosis, rigidez matutina y dolores articulares degenerativos o producidos por el frío.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Lavanda e Hipérico', 'Armonía y equilibrio integral. Calma la irritación dérmica, relaja el sistema nervioso central y facilita la desconexión mental y el sosiego.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Consuelda, Cannabis y Clavo de Olor', 'Tratamiento intensivo analgésico de triple acción. Alivio inmediato para dolores intensos musculares, contracturas lumbares y afecciones articulares.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Cannabis y Caléndula', 'Combinación equilibrada de relajación muscular y cuidado dérmico. Desinflama la zona mientras regenera e hidrata profundamente la piel.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Lavanda y Rosa', 'Cuidado facial y corporal sedoso. Suaviza la piel, relaja los sentidos y proporciona una experiencia aromaterapéutica relajante de descanso.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Árnica', 'Pomada antiinflamatoria por excelencia. Acelera la reabsorción de hematomas, calma torceduras, esguinces, moretones y dolores por traumatismos.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Hipérico, Consuelda y Alcanfor', 'Fórmula sinérgica regeneradora y analgésica. Ideal para deportistas o trabajos con esfuerzo físico, repara fibras musculares y ligamentos.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Cannabis, Aloe Vera y Esencia de Rosa', 'Emulsión hidratante facial antiedad de textura liviana. Nutrición celular profunda, frescura calmante y aroma sutil de rosas silvestres.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema de Jazmín', 'Crema humectante sensorial de jazmín blanco. Despierta sensaciones de optimismo, nutre la piel seca y disipa tensiones acumuladas en el día.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Crema Cítrica', 'Tonificante dérmico energizante elaborado con notas cítricas patagónicas. Devuelve la vitalidad a la piel apagada y aporta frescura matutina.', '/productos/crema_estudio.jpg', true),
  ('5238e833-b473-4393-a902-ed3321b9df96', 'Bálsamo Labial de Caléndula y Cera Pura', 'Nutrición y protección inmediata para labios resecos o paspados por el viento andino. Elaborado con cera pura de abejas y caléndula.', '/productos/crema_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite Bebible de Ortiga', 'Maceración pura rica en hierro orgánico, clorofila y minerales esenciales. Remineralizante para combatir anemia, fatiga y purificar la sangre. Apto uso interno.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite Bebible de Pañil', 'Extracto oleoso de la flora nativa patagónica. Protector hepático, depurativo biliar y reconstituyente gástrico. 10 a 15 gotas sublinguales o en agua.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite Bebible de Hinojo', 'Macerado carminativo y digestivo natural. Elimina gases, calma cólicos intestinales, relaja espasmos digestivos y favorece digestiones livianas.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite Bebible de Diente de León', 'Excelente tónico depurativo para el hígado y riñones. Estimula la secreción de bilis, depura impurezas orgánicas y mejora la asimilación nutricional.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite de Caléndula', 'Maceración solar en aceite puro de flores de caléndula. Emoliente ultra suave para pieles sensibles, cicatrización y dermatitis. Apto bebés y mamás.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite Bebible Memory MIX 8', 'Fórmula neuroestimulante con 8 hierbas sinérgicas. Mejora la oxigenación cerebral, retención nemotécnica, agilidad mental y claridad en jornadas intensas.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite Bebible y Corporal MIX 31', 'Sinergia maestra polivalente. Se puede ingerir como tónico equilibrador o aplicar en sienes, nuca y zonas tensionales para alivio inmediato del dolor de cabeza.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite de Cannabis Medicinal', 'Extracto fitoterapéutico de amplio espectro. Calma dolores articulares crónicos, modula estados de insomnio y relaja contracturas severas.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite Rescate', 'Fórmula armonizadora para momentos de crisis, shock emocional, estrés agudo y ataques de pánico. Aporta calma, templanza y equilibrio emocional.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite de Rosa Mosqueta Puro', 'Puro de primera prensada en frío de la Comarca Andina. Altísima concentración de retinol natural y vitamina C. Regenera cicatrices, arrugas y estrías.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite de Consuelda', 'Macerado oleoso específico para ligamentos, articulaciones y huesos. Acelera la recuperación en esguinces, fisuras, desgarros y tendinitis.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite Articulaciones', 'Óleo medicinal formulado para fricciones en zonas rígidas o afectadas por reuma y artrosis. Penetra profundamente estimulando la movilidad.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite de Hipérico (Hierba de San Juan)', 'El legendario aceite bermellón. Analgésico y desinflamante para pinzamientos del nervio ciático, dolores lumbares, quemaduras superficiales y hematomas.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite de Enebro', 'Macerado calorífico descontracturante. Muy apreciado para masajes corporales deportivos, alivia calambres y prepara los músculos para el movimiento.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite Bebible de Cúrcuma', 'Extracto bebible rico en curcuminoides biodisponibles. Potente antiinflamatorio sistémico celular, protege el sistema gastrointestinal y las articulaciones.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite de Orégano', 'Concentrado botánico de carvacrol. Antimicrobiano natural, combate levaduras y parásitos, estimula el sistema inmunológico y depura el organismo.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite de Alcanfor', 'Aceite para masajes estimulantes y circulatorios. Reactiva zonas entumecidas por el frío, alivia fatiga muscular y despeja tensiones corporales.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite Bálsamo Pectoral', 'Óleo para fricción pectoral con esencias descongestivas andinas. Facilita la respiración fluida y el descanso nocturno en estados gripales.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite de Árnica y Clavo de Olor', 'Fórmula de gran poder analgésico tópico. El eugenol del clavo y la helenalina del árnica calman dolores punzantes en articulaciones y tendones.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite de Hipérico, Alcanfor, Consuelda y Cannabis', 'Fórmula magistral de cuatro principios activos combinados. Alivio integral de choque para dolores musculares severos, lumbagos y ciática.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite para Masajes Intensivo 5 Hierbas', 'Presentación especial para masajistas y terapeutas. Combinación de Hipérico, Consuelda, Alcanfor, Cannabis y Clavo para sesiones descontracturantes.', '/productos/aceite_masaje_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite para Masajes Drenaje Linfático', 'Mezcla oleosa activadora de la circulación de retorno. Facilita las maniobras de drenaje linfático manual y ayuda a descongestionar piernas hinchadas.', '/productos/aceite_masaje_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite para Masajes Pie Diabético', 'Fórmula protectora altamente humectante. Diseñada para reactivar la microcirculación periférica, prevenir grietas y nutrir la piel vulnerable.', '/productos/aceite_masaje_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite Bebible Antiparasitario', 'Combinación tradicional de hierbas depurativas que ayudan a expulsar parásitos intestinales y desintoxicar el tracto digestivo de forma natural.', '/productos/gotero_estudio.jpg', true),
  ('9e5df32b-0f1c-401a-a5b6-61550583e120', 'Aceite de Cannabis y Caléndula', 'Óleo calmante dual para masajes y aplicaciones dérmicas. Une el poder desinflamante del cannabis con la profunda reparación celular de la caléndula.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Diente de León', 'Extracto hidroalcohólico puro de Taraxacum officinale. Excelente desintoxicante hepático y renal. Tomar 20 gotas en medio vaso de agua antes de las comidas.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Ortiga', 'Extracto concentrado silvestre rico en hierro y oligoelementos. Indicado para decaimiento físico, caída del cabello, anemias estacionales y purificación.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Caléndula', 'Reguladora y protectora interna. Posee notables efectos antiinflamatorios digestivos, ayuda a regular el ciclo femenino y estimula las defensas orgánicas.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Consuelda', 'Concentrado botánico de alantoína para estimulación y regeneración celular. Apoya la recuperación de fisuras óseas, roturas fibrilares y ligamentos.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Cannabis', 'Extracto herbal hidroalcohólico que modula el sistema endocannabinoide. Favorece la distensión muscular, induce al sueño y modula dolores crónicos.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Hipérico', 'El célebre antidepresivo y equilibrador del ánimo natural. Disipa la melancolía, alivia la ansiedad y restaura la energía anímica interior.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Pañil', 'Medicina ancestral de los bosques patagónicos. Cicatrizante estomacal para gastritis, úlceras digestivas y desinflamación de mucosas.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Enebro', 'Poderoso diurético natural. Facilita la depuración renal, ayuda a eliminar el exceso de ácido úrico y combate la retención hídrica corporal.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Cúrcuma', 'Extracto hidroalcohólico concentrado de cúrcuma pura. Hepatoprotectora, antiinflamatoria articular y protectora de la salud cardiovascular.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre Memo MIX', 'Sinergia botánica nootrópica para estudiantes y profesionales. Estimula la concentración sostenida, la lucidez mental y la memoria de retención.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre Rescate', 'Gotas de serenidad inmediata ante situaciones de angustia, susto, pánico o nerviosismo agudo. Restablece la paz mental y la estabilidad emocional.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre Melena de León', 'Extracto del poderoso hongo adaptógeno Hericium erinaceus. Fomenta el factor de crecimiento nervioso (NGF), la plasticidad cerebral y la salud digestiva.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Jarilla', 'Arbusto sagrado de la estepa andina. Potente depurativo orgánico, alivia afecciones respiratorias, reumatismo y purifica el torrente sanguíneo.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Llantén', 'Elaborada con hojas frescas de llantén patagónico. Descongestiva y suavizante de vías respiratorias, calma la tos seca y cicatriza mucosas.', '/productos/gotero_estudio.jpg', true),
  ('5fcfa6d7-4f51-4b3f-921c-6fe48ee094be', 'Tintura Madre de Melisa', 'Melisa cordillerana sedante suave y antiespasmódica. Alivia la irritabilidad nerviosa, palpitaciones por estrés y garantiza un descanso reparador.', '/productos/gotero_estudio.jpg', true),
  ('859b21c0-4489-41ef-824d-cf2a90107095', 'Sales de Baño: Rosa, Clavo de Olor e Hibiscus', 'Sales minerales patagónicas con flores de hibiscus, pétalos de rosa y clavo. Baño relajante para el corazón, suaviza la piel y brinda contención sensorial.', '/productos/sales_estudio.jpg', true),
  ('859b21c0-4489-41ef-824d-cf2a90107095', 'Sales de Baño: Cítrica, Ruda y Diente de León', 'Mezcla depurativa y de limpieza energética. Ideal para pediluvios nocturnos que descargan la pesadez de los pies, estimulan la circulación y quitan tensiones.', '/productos/sales_estudio.jpg', true),
  ('859b21c0-4489-41ef-824d-cf2a90107095', 'Sales de Baño: Jazmín, Canela, Romero y Salvia', 'Sales reconfortantes y tonificantes. El romero y la salvia despejan el cuerpo cansado, mientras la canela y el jazmín aportan calidez vital.', '/productos/sales_estudio.jpg', true),
  ('859b21c0-4489-41ef-824d-cf2a90107095', 'Sales de Baño: Sándalo, Manzanilla y Pasionaria', 'Sinergia calmante profunda para baños de inmersión antes de acostarse. Aquietan la mente inquieta y facilitan un sueño reparador continuo.', '/productos/sales_estudio.jpg', true),
  ('859b21c0-4489-41ef-824d-cf2a90107095', 'Sales de Baño: Lavanda, Hipérico y Canela', 'Especialmente formuladas para aliviar dolores musculares y lumbares. Descontracturan la musculatura y disipan el cansancio tras un día agitado.', '/productos/sales_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Bruma Áurica de Jazmín', 'Hidrolato floral con notas puras de jazmín blanco. Despierta sensaciones de optimismo, calidez afectiva y armoniza el campo vibracional personal.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Bruma Áurica Cítrica', 'Elixir energizante con aceites esenciales de naranja dulce, limón y bergamota. Despeja el cansancio mental, alegra los ambientes y renueva la energía.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Bruma Áurica de Lavanda', 'Destilado puro de lavandas andinas. Promueve paz mental instantánea. Ideal para vaporizar sobre almohadas, sábanas o en la habitación del bebé.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Bruma Áurica de Bosque Andino', 'Notas de Ciprés cordillerano, Coihue y Pino Oregón. Brinda arraigo a la tierra, purifica el aire de espacios cerrados y conecta con la serenidad del bosque.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Bruma Áurica de Rosas y Cedro', 'Sinergia armonizadora que conecta con el chakra cardíaco. Destilado de rosas de jardín patagónico con notas de cedro. Contención emocional y calidez.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Bruma Áurica de Lavanda y Salvia Blanca', 'Elixir purificador del campo áurico y limpieza espacial. Disipa energías densas en consultorios, hogares o espacios de meditación.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Coco Tropical', 'Aroma dulce y envolvente con notas de coco natural. Transforma cualquier ambiente en un espacio cálido, exótico y relajado.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Naranja Andina', 'Frescura cítrica dulce y chispeante. Aporta luminosidad y vitalidad al hogar o local comercial, eliminando olores persistentes.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Limón Silvestre', 'Máxima sensación de frescura, limpieza y claridad mental. Aroma estimulante perfecto para cocinas, oficinas y áreas de trabajo.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Manzana Verde', 'Nota frutal crujiente, dulce y equilibrada. Despierta recuerdos acogedores y deja una estela aromática fresca y apetecible.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Frutilla Silvestre', 'Dulzura frutal alegre y jovial inspirada en las bayas cordilleranas. Ambientación duradera para salas de estar y dormitorios.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Uva Dulce', 'Aroma frutal profundo y persistente con notas avainilladas y de uva madura. Crea un entorno distinguido y perfumado.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Violeta', 'Delicada fragancia floral clásica. Suave, sutil y elegante, recomendada para ambientes de descanso o vestidores.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Pétalos de Rosa', 'El clásico y distinguido aroma floral de la rosa de verano. Llena los espacios de armonía, romanticismo y sosiego.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Bouquet Floral', 'Combinación equilibrada de flores andinas frescas. Una brisa primaveral permanente para aromatizar el hogar.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Sándalo Oriental', 'Madera sagrada aromática de notas cálidas y profundas. Fomenta la concentración, la meditación y el recogimiento espiritual.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Almendra Dulce', 'Aroma cremoso, suave y reconfortante. Brinda sensación de protección y bienestar en espacios familiares.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Ambiental Vainilla Colonial', 'Dulzura gourmand que reconforta y genera una atmósfera sumamente cálida y acogedora en cualquier rincón del hogar.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Textil 212', 'Aroma sofisticado de inspiración urbana y cosmopolita. Ideal para vaporizar sobre cortinas, tapizados, ropa de cama y placard.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Textil Flower', 'Notas florales empolvadas, suaves y delicadas. Deja una estela fresca y distinguida en telas y prendas de vestir.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Textil Amor', 'Esencia cautivante y romántica para textiles. Ideal para perfumar dormitorios, acolchados y sábanas de manera perdurable.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Textil FRH', 'Sensación de pureza y frescura extrema de ropa recién secada al aire libre de la Patagonia. Limpieza y distinción textil.', '/productos/bruma_estudio.jpg', true),
  ('9cddbc4a-d91a-42d0-9fff-d637235903b8', 'Fragancia Textil Kenzo', 'Brisa floral acuática fresca y zen. Vaporizá sobre prendas para disfrutar de una sensación revitalizante y placentera todo el día.', '/productos/bruma_estudio.jpg', true),
